import {scheduler} from 'node:timers/promises';import {setImmediate} from 'node:timers';
export {scheduler};export async function run(names){const rows=[],progress=[];
for(let i=0;i<names.length;i++){progress.push('batch:'+i);setImmediate(()=>progress.push('peer:'+i));
await scheduler.yield();rows.push(JSON.stringify({index:i,name:names[i]})+'\n');progress.push('resume:'+i);}
await scheduler.wait(1);return {rows,progress};}

